------------ define ------------
local DEFAULT_SHOW_PRESS_SIGN_TIME = 0.2
local PATH_ANIM_EMPTY = "Empty"
local PATH_ANIM_PLAY = "Play"
------------ define ------------

---@class LongTapSign
---@field Root_Anim                     	UnityEngine.Animator
---@field Img_Process                   	UnityEngine.UI.Image
local LongTapSign = Class('LongTapSign')

function LongTapSign:__init()
    self.coShowProcess = nil
    self.rectTrans = nil
    self.startTime = nil
    self.coShowProcess = nil
end

function LongTapSign:__delete()
    self.coShowProcess = nil
    self.rectTrans = nil
    self.startTime = nil
    self.coShowProcess = nil
end

function LongTapSign:Awake()
end

function LongTapSign:Start()
end

---SetNodePosition
---设置 节点 位置
---@param pos Vector3 Node 位置
function LongTapSign:SetNodePosition(pos)
    self.controller.transform.anchoredPosition = pos
end

---SetProcessState
---设置 长按 提示展示
---@param boolean boolean @ 是否展示
function LongTapSign:SetProcessState(boolean)
    self:ChangeAnim()
    if boolean or IsNull(boolean) then
        self.startTime = os.clock()
        self.coShowProcess = cs_coroutine.start(function()
            while os.clock() - self.startTime <= DEFAULT_SHOW_PRESS_SIGN_TIME do
                local processTime = os.clock() - self.startTime
                self.Img_Process.fillAmount = processTime / DEFAULT_SHOW_PRESS_SIGN_TIME
                cs_coroutine.yield_return()
            end
            self.Img_Process.fillAmount = 1
            self.coShowProcess = nil
        end)
    else
        if not IsNull(self.coShowProcess) then
            cs_coroutine.stop(self.coShowProcess)
            self.coShowProcess = nil
        end
        self.startTime = nil
        self.Img_Process.fillAmount = 0
    end
end

function LongTapSign:ChangeAnim(showPlay)
    if not IsNull(self.Root_Anim) then
        self.Root_Anim:Play(showPlay and PATH_ANIM_PLAY or PATH_ANIM_EMPTY, 0, 0)
    end
end

function LongTapSign:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

